from concurrent.futures import ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    """Return x if it is even; raise Bad(x) if it is odd."""
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Check every element of xs in parallel using a thread pool.

    Returns the checked values in their original order. If any element is
    odd, raises the Bad for the lowest-index odd element.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(check, xs))


def test_check_even_returns_value() -> None:
    assert check(4) == 4


def test_check_odd_raises_bad() -> None:
    with pytest.raises(Bad) as info:
        check(7)
    assert info.value.n == 7


def test_all_even_returns_values_in_order() -> None:
    assert all_even([2, 4, 6]) == [2, 4, 6]


def test_all_even_empty_list() -> None:
    assert all_even([]) == []


def test_all_even_raises_for_single_odd() -> None:
    with pytest.raises(Bad) as info:
        all_even([2, 3, 4])
    assert info.value.n == 3


def test_all_even_raises_lowest_index_odd() -> None:
    with pytest.raises(Bad) as info:
        all_even([2, 5, 4, 9, 8])
    assert info.value.n == 5


def test_all_even_first_element_odd() -> None:
    with pytest.raises(Bad) as info:
        all_even([1, 2, 4])
    assert info.value.n == 1
